#include "digitor/qualifier.hpp"
#include <algorithm>
#include <cmath>
#include <stdexcept>
namespace digitor {namespace{float weight(float x,QualifierRange r){float s=std::max(0.f,r.softness);if(x>=r.low&&x<=r.high)return 1;if(s&&x<r.low&&x>r.low-s)return(x-r.low+s)/s;if(s&&x>r.high&&x<r.high+s)return(r.high+s-x)/s;return 0;}void hsl(Color c,float&h,float&s,float&l){float hi=std::max({c.r,c.g,c.b}),lo=std::min({c.r,c.g,c.b}),d=hi-lo;l=(hi+lo)/2;s=d/(1-std::abs(2*l-1)+1e-8f);h=0;if(d){if(hi==c.r)h=std::fmod((c.g-c.b)/d,6.f);else if(hi==c.g)h=(c.b-c.r)/d+2;else h=(c.r-c.g)/d+4;h/=6;if(h<0)h++;}}}
void HslQualifier::sample(Color c){float h,s,l;hsl(c,h,s,l);settings_.hue={h,h,0.05f};settings_.saturation={s,s,0.1f};settings_.luminance={l,l,0.1f};}void HslQualifier::sample(std::span<const Color>c){if(c.empty())return;float h=0,s=0,l=0;for(auto x:c){float a,b,d;hsl(x,a,b,d);h+=a;s+=b;l+=d;}sample(Color{});float n=float(c.size());settings_.hue={h/n,h/n,.05f};settings_.saturation={s/n,s/n,.1f};settings_.luminance={l/n,l/n,.1f};}
std::vector<float> HslQualifier::matte_cpu(std::span<const Color>in,uint32_t w,uint32_t h)const{if(in.size()!=size_t(w)*h)throw std::invalid_argument("image size");std::vector<float> m(in.size());for(size_t i=0;i<in.size();i++){float a,b,c;hsl(in[i],a,b,c);float v=weight(a,settings_.hue)*weight(b,settings_.saturation)*weight(c,settings_.luminance);v=v<settings_.clean_black?0:v>1-settings_.clean_white?1:v;if(settings_.invert)v=1-v;m[i]=v;}unsigned radius=(unsigned)std::ceil(settings_.blur);if(radius){auto src=m;for(uint32_t y=0;y<h;y++)for(uint32_t x=0;x<w;x++){float sum=0;unsigned n=0;for(int yy=std::max(0,int(y)-int(radius));yy<=std::min(int(h)-1,int(y)+int(radius));yy++)for(int xx=std::max(0,int(x)-int(radius));xx<=std::min(int(w)-1,int(x)+int(radius));xx++){sum+=src[yy*w+xx];n++;}m[y*w+x]=sum/n;}}if(settings_.denoise>0)for(auto&v:m)v=std::clamp((v-.5f)*(1+settings_.denoise)+.5f,0.f,1.f);return m;}void HslQualifier::matte_gpu(CommandEncoder&e,std::span<const Color>i,std::span<float>o,uint32_t w,uint32_t h)const{if(o.size()!=i.size())throw std::invalid_argument("matte size");e.dispatch([=,this]{auto m=matte_cpu(i,w,h);std::copy(m.begin(),m.end(),o.begin());});}
}
